begin;
create temp table assertions(label text);
grant select,insert on assertions to authenticated;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAILED: %',label;end if;insert into assertions values(label);end$$;
insert into auth.users(id,email,is_anonymous) values('12000000-0000-4000-8000-000000000001','board-a@qa.invalid',false),('12000000-0000-4000-8000-000000000002','board-b@qa.invalid',false),('12000000-0000-4000-8000-000000000003',null,true),('12000000-0000-4000-8000-000000000004',null,true);
insert into public.classes(id,owner_id,label,grade,student_count,runtime_mode) values('12000000-0000-4000-8000-000000000005','12000000-0000-4000-8000-000000000001','7K',7,3,'demo');
insert into pn_private.presentation_sessions(id,class_id,owner_id) values('12000000-0000-4000-8000-000000000006','12000000-0000-4000-8000-000000000005','12000000-0000-4000-8000-000000000001');
insert into pn_private.presentations(id,session_id,owner_id,board_id,channel_epoch,public_state) values('12000000-0000-4000-8000-000000000007','12000000-0000-4000-8000-000000000006','12000000-0000-4000-8000-000000000001','12000000-0000-4000-8000-000000000003','12000000-0000-4000-8000-000000000008','{"schemaVersion":1,"mode":"station","question":1,"taskEpoch":"12000000-0000-4000-8000-000000000009","groups":[]}');
create temp table data(profile jsonb,binding jsonb,command jsonb);
insert into data values('{"schemaVersion":1,"touches":2,"pointerEvents":true,"indexedDb":true,"serviceWorker":true,"width":1920,"heightPixels":1080,"browser":"chromium","major":140,"samples":5,"medianMs":20,"p95Ms":40,"height":"normal","durationSeconds":60}',
'{"presentationId":"12000000-0000-4000-8000-000000000007","channelEpoch":"12000000-0000-4000-8000-000000000008","taskEpoch":"12000000-0000-4000-8000-000000000009"}',
'{"id":"12000000-0000-4000-8000-000000000011","instanceId":"12000000-0000-4000-8000-000000000010","taskEpoch":"12000000-0000-4000-8000-000000000009","sequence":1,"input":{"kind":"activate","x":0.5,"y":0.5}}');
grant select,update on data to authenticated;
select pg_temp.ok(not has_table_privilege('authenticated','pn_private.board_profiles','SELECT'),'profile private table denied');
select pg_temp.ok(not has_table_privilege('authenticated','pn_private.remote_tools','INSERT'),'remote table direct write denied');
select pg_temp.ok(not pn_private.matches_sync_schema('{}','{}'),'malformed schema fails closed');
select pg_temp.ok(not pn_private.matches_sync_schema('{"oneOf":[{"type":"number"},{"type":"number"}]}','1'),'oneOf requires exactly one branch');
set local role authenticated;
set local request.jwt.claims='{"sub":"12000000-0000-4000-8000-000000000003","is_anonymous":true}';
select pg_temp.ok((select public.board_profile_action('save',profile||'{"name":"PRIVATE"}')->>'error'='INVALID_INPUT' from data),'profile name rejected');
select pg_temp.ok((select public.board_profile_action('save',profile)->>'saved'='true' from data),'board profile saved');
select pg_temp.ok((select public.board_profile_action('read',jsonb_build_object('presentationId',binding->'presentationId'))->>'error'='FORBIDDEN' from data),'board cannot query teacher profiles');
select pg_temp.ok((select public.remote_tool_action('join',binding||'{"action":"join","instanceId":"12000000-0000-4000-8000-000000000010"}')->>'instanceId'='12000000-0000-4000-8000-000000000010' from data),'board joins current task');
select pg_temp.ok((select public.remote_tool_action('send',binding||jsonb_build_object('action','send','command',command))->>'error'='FORBIDDEN' from data),'board cannot send remote command');
select pg_temp.ok(public.remote_topic_allowed('pn:input:12000000-0000-4000-8000-000000000007:12000000-0000-4000-8000-000000000008'),'paired board input topic');
set local request.jwt.claims='{"sub":"12000000-0000-4000-8000-000000000004","is_anonymous":true}';
select pg_temp.ok(not public.remote_topic_allowed('pn:input:12000000-0000-4000-8000-000000000007:12000000-0000-4000-8000-000000000008'),'other board no input topic');
select pg_temp.ok((select public.remote_tool_action('read',binding||'{"action":"read"}')->>'error'='FORBIDDEN' from data),'other board cannot read input');
set local request.jwt.claims='{"sub":"12000000-0000-4000-8000-000000000002","is_anonymous":false}';
select pg_temp.ok((select public.board_profile_action('read',jsonb_build_object('presentationId',binding->'presentationId'))->>'error'='FORBIDDEN' from data),'other teacher cannot query profile');
select pg_temp.ok((select public.remote_tool_action('send',binding||jsonb_build_object('action','send','command',command))->>'error'='FORBIDDEN' from data),'other teacher cannot send input');
set local request.jwt.claims='{"sub":"12000000-0000-4000-8000-000000000001","is_anonymous":false}';
select pg_temp.ok((select public.board_profile_action('read',jsonb_build_object('presentationId',binding->'presentationId'))=profile from data),'owner reads paired profile');
select pg_temp.ok((select public.board_profile_action('save',profile)->>'error'='FORBIDDEN' from data),'teacher cannot impersonate board profile');
select pg_temp.ok((select public.remote_tool_action('read',binding||'{"action":"read","name":"PRIVATE"}')->>'error'='INVALID_INPUT' from data),'remote extra field denied by SQL');
select pg_temp.ok((select public.remote_tool_action('send',binding||jsonb_build_object('action','send','command',jsonb_set(command,'{input}','{"kind":"reveal"}')))->>'error'='INVALID_INPUT' from data),'remote reveal denied');
select pg_temp.ok((select public.remote_tool_action('send',binding||jsonb_build_object('action','send','command',jsonb_set(command,'{input,x}','2')))->>'error'='INVALID_INPUT' from data),'remote coordinate range checked');
select pg_temp.ok((select public.remote_tool_action('send',binding||jsonb_build_object('action','send','command',command))->'command'=command from data),'owner remote command accepted');
select pg_temp.ok((select public.remote_tool_action('send',binding||jsonb_build_object('action','send','command',command))->>'sequence'='1' from data),'same input retry idempotent');
select pg_temp.ok((select public.remote_tool_action('send',binding||jsonb_build_object('action','send','command',jsonb_set(command,'{input,x}','0.3')))->>'error'='CONFLICT' from data),'same command changed payload denied');
select pg_temp.ok((select public.remote_tool_action('send',binding||jsonb_build_object('action','send','command',command||'{"id":"12000000-0000-4000-8000-000000000012","sequence":2}'))->>'error'='CONFLICT' from data),'terminal input waits for ACK');
set local request.jwt.claims='{"sub":"12000000-0000-4000-8000-000000000003","is_anonymous":true}';
select pg_temp.ok((select public.remote_tool_action('ack',binding||'{"action":"ack","instanceId":"12000000-0000-4000-8000-000000000010","receipt":{"id":"12000000-0000-4000-8000-000000000011","applied":true,"editable":false}}')->'receipt'->>'applied'='true' from data),'board ACK accepted');
set local request.jwt.claims='{"sub":"12000000-0000-4000-8000-000000000001","is_anonymous":false}';
update data set command=command||'{"id":"12000000-0000-4000-8000-000000000012","sequence":2,"input":{"kind":"move","x":0.6,"y":0.6}}';
select pg_temp.ok((select public.remote_tool_action('send',binding||jsonb_build_object('action','send','command',command))->>'sequence'='2' from data),'move accepted after terminal ACK');
select pg_temp.ok((select public.remote_tool_action('send',binding||jsonb_build_object('action','send','command',command||'{"id":"12000000-0000-4000-8000-000000000013","sequence":3}'))->>'error'='RATE_LIMITED' from data),'moves capped at ten Hz');
reset role;
update pn_private.remote_tools set sent_at=clock_timestamp()-interval '4 seconds';
set local role authenticated;
set local request.jwt.claims='{"sub":"12000000-0000-4000-8000-000000000003","is_anonymous":true}';
select pg_temp.ok((select public.remote_tool_action('read',binding||'{"action":"read"}')->'command'='null'::jsonb from data),'expired input not replayed');
select pg_temp.ok((select public.remote_tool_action('join',binding||'{"action":"join","instanceId":"12000000-0000-4000-8000-000000000014"}')->>'sequence'='0' from data),'board reload rotates instance and clears mailbox');
set local request.jwt.claims='{"sub":"12000000-0000-4000-8000-000000000001","is_anonymous":false}';
select pg_temp.ok((select public.remote_tool_action('send',binding||jsonb_build_object('action','send','command',command))->>'error'='CONFLICT' from data),'old board instance command denied');
select pg_temp.ok((select public.remote_tool_action('read',binding||'{"action":"read","taskEpoch":"12000000-0000-4000-8000-000000000015"}')->>'error'='CONFLICT' from data),'old task epoch denied');
reset role;
update pn_private.presentations set public_state=jsonb_set(public_state,'{mode}','"reflection"') where id='12000000-0000-4000-8000-000000000007';
set local role authenticated;
set local request.jwt.claims='{"sub":"12000000-0000-4000-8000-000000000001","is_anonymous":false}';
select pg_temp.ok((select public.remote_tool_action('read',binding||'{"action":"read"}')->>'error'='FORBIDDEN' from data),'reflection never accepts remote input');
reset role;
update pn_private.presentations set revoked=true;
set local role authenticated;
select pg_temp.ok(not public.remote_topic_allowed('pn:input:12000000-0000-4000-8000-000000000007:12000000-0000-4000-8000-000000000008'),'revoked input topic denied');
select 'PASS '||count(*)||' board capability/remote SQL assertions' from assertions;
select 'ok - '||label from assertions;
rollback;
